import fs from 'node:fs/promises';
import path from 'node:path';
import {fileURLToPath} from 'node:url';

const project=path.dirname(path.dirname(fileURLToPath(import.meta.url)));
const readJSON=async name=>JSON.parse((await fs.readFile(path.join(project,name),'utf8')).replace(/^\uFEFF/,''));
const content=await readJSON('content.json');
const state=await readJSON('campaign-state.json');
const mobile=content.tiers.filter(t=>t.platform==='手游');
const expectedOld=[188,388,688,888],prices=[188,388,588,788],guarantees=[188,488,888,1288];
if(mobile.length!==2||mobile.some(t=>JSON.stringify(t.rows.map(r=>r.priceR))!==JSON.stringify(expectedOld)||JSON.stringify(t.rows.map(r=>r.excessGuaranteeW))!==JSON.stringify(guarantees)))throw Error('Expected prior mobile prices and guarantees; refuse to overwrite a different revision.');
const backup=path.join(project,'review','before-price-r2');
await fs.mkdir(backup,{recursive:true});
for(const name of ['content.json','campaign-state.json','layout.json','output/manifest.json'])await fs.copyFile(path.join(project,name),path.join(backup,path.basename(name)));
for(const tier of mobile)tier.rows.forEach((row,i)=>row.priceR=prices[i]);
const pageIds=['mobile-absolute','mobile-secret','social'];
const source='source-references/mobile-price-update-20261009.png';
content.deliveryPageIds=pageIds;
content.provenance.prices='2026-10-09：手游机密与绝密按用户价格截图的新价格列更新为188/388/588/788r，对应超额累计保底188/488/888/1288w。广告中的端游价目沿用用户提供的现有广告和此前已确认源稿。';
content.provenance.priceSourceByPlatform={desktop:'用户本轮广告截图 source-references/social-before-price-update-20261009.png 与此前已确认 content.json；端游价目继续沿用。',mobile:'用户本轮价格截图 '+source+' 的J列新价格，与E列超额累计保底逐行对应；绝密和机密一致。'};
content.provenance.sourceFiles=[...new Set([...content.provenance.sourceFiles,source,'source-references/social-before-price-update-20261009.png','source-references/mobile-absolute-before-price-update-20261009.png','source-references/mobile-secret-before-price-update-20261009.png'])];
content.provenance.priceRevision={date:'2026-10-09',basis:'用户要求更新超额累计单广告页和手游价格表',changes:[{oldPriceR:688,newPriceR:588,excessGuaranteeW:888},{oldPriceR:888,newPriceR:788,excessGuaranteeW:1288}],modes:['绝密','机密']};
state.revisionHistory=[...(state.revisionHistory??[]),{revision:state.revision,package:state.package,basis:state.contentVerificationBasis}];
state.deliveryScope={pageIds,platforms:['desktop','mobile'],basis:'用户明确点名超额累计单广告页及手游机密、绝密价格表，共3页；广告包含两端价目。'};
state.verifiedPricePlatforms=['desktop','mobile'];
state.priceSourceByPlatform=content.provenance.priceSourceByPlatform;
state.contentVerified=true;
state.contentVerificationBasis=content.provenance.prices+' 门槛、机制、补偿与下单须知沿用此前已确认内容。';
state.plannedDeliverables=['手游·绝密四档价目','手游·机密四档价目','超额累计单广告页'];
state.revision='excess-mobile-price-r2-20261009';
state.stage='price-update';
state.nextStep='仅导出本轮3页并完成实际PNG、手机预览及改价区复检。';
state.vectorDelivery={status:'in-progress',review:'review/index.html',formats:['PNG','editable text SVG','outlined SVG'],pageIds};
delete state.package;
for(const [name,value] of [['content.json',content],['campaign-state.json',state]])await fs.writeFile(path.join(project,name),JSON.stringify(value,null,2)+'\n');
console.log(JSON.stringify({pageIds,prices,guarantees,modes:mobile.map(t=>t.mode)}));
